const DEVELOPMENT_GATE = false;
if (!DEVELOPMENT_GATE) throw new Error('DEVELOPMENT_GATE_CLOSED: approve a bounded product test before changing this value');
return [{ json: { after: null, page: 1, maxPages: 50 } }];

const response = $json.data?.products;
if (!response) throw new Error('SHOPIFY_PRODUCTS_RESPONSE_INVALID');
const numericId = gid => Number(String(gid || '').split('/').pop()) || null;
const products = []; const variants = [];
for (const p of response.nodes || []) {
  const productId = Number(p.legacyResourceId) || numericId(p.id);
  products.push({ shopify_product_id: productId, title: p.title, handle: p.handle, status: String(p.status || '').toLowerCase(), vendor: p.vendor, product_type: p.productType, tags: p.tags || [], image_url: p.featuredMedia?.preview?.image?.url || null, shopify_updated_at: p.updatedAt, raw: p });
  for (const v of p.variants?.nodes || []) variants.push({ shopify_variant_id: Number(v.legacyResourceId) || numericId(v.id), shopify_product_id: productId, title: v.title, sku: v.sku, barcode: v.barcode, price: Number(v.price || 0), compare_at_price: v.compareAtPrice == null ? null : Number(v.compareAtPrice), inventory_quantity: v.inventoryQuantity, image_url: v.image?.url || p.featuredMedia?.preview?.image?.url || null, shopify_updated_at: v.updatedAt, raw: v });
}
return [{ json: { products, variants, pageInfo: response.pageInfo, safety: { page: 1, maxPages: 50 } } }];
